<?php

declare(strict_types=1);

use EventMenu\Core\Auth;
use EventMenu\Core\Database;
use EventMenu\Core\Security;

Auth::requirePermission('catalog.manage');$tenantId=em_require_tenant();$unitId=Auth::unitId();
if($_SERVER['REQUEST_METHOD']==='POST'){em_post_csrf();$action=(string)($_POST['action']??'');try{
    if($action==='category-save'){$id=(int)($_POST['id']??0);$name=trim((string)($_POST['name']??''));if($name==='')throw new RuntimeException('Categoria inválida.');$u=(int)($_POST['unit_id']??0);if($id){$pdo->prepare('UPDATE categories SET unit_id=?,name=?,sort_order=?,active=? WHERE id=? AND tenant_id=?')->execute([$u?:null,$name,(int)($_POST['sort_order']??0),isset($_POST['active'])?1:0,$id,$tenantId]);}else{$pdo->prepare('INSERT INTO categories (tenant_id,unit_id,name,sort_order,active) VALUES (?,?,?,?,1)')->execute([$tenantId,$u?:null,$name,(int)($_POST['sort_order']??0)]);$id=(int)$pdo->lastInsertId();}Auth::audit('category.saved','category',(string)$id);em_flash('ok','Categoria salva.');}
    elseif($action==='category-toggle'){$pdo->prepare('UPDATE categories SET active=1-active WHERE id=? AND tenant_id=?')->execute([(int)$_POST['id'],$tenantId]);em_flash('ok','Categoria atualizada.');}
    elseif($action==='category-delete'){$id=(int)$_POST['id'];$c=$pdo->prepare('SELECT COUNT(*) FROM products WHERE category_id=? AND tenant_id=?');$c->execute([$id,$tenantId]);if((int)$c->fetchColumn()>0)throw new RuntimeException('Mova os produtos antes de excluir a categoria.');$pdo->prepare('DELETE FROM categories WHERE id=? AND tenant_id=?')->execute([$id,$tenantId]);em_flash('ok','Categoria excluída.');}
    elseif($action==='product-save'){
        $id=(int)($_POST['id']??0);$name=trim((string)($_POST['name']??''));$sku=trim((string)($_POST['sku']??''));$price=(int)round((float)str_replace(',','.',(string)($_POST['price']??'0'))*100);$promoRaw=trim((string)($_POST['promo_price']??''));$promo=$promoRaw===''?null:(int)round((float)str_replace(',','.',$promoRaw)*100);$cat=(int)($_POST['category_id']??0);$u=(int)($_POST['unit_id']??0);$stock=(float)str_replace(',','.',(string)($_POST['stock_qty']??'0'));$minStock=(float)str_replace(',','.',(string)($_POST['min_stock_qty']??'0'));$track=isset($_POST['track_stock'])?1:0;if($name===''||$price<0||($promo!==null&&$promo<0))throw new RuntimeException('Produto inválido.');if($cat){$c=$pdo->prepare('SELECT id FROM categories WHERE id=? AND tenant_id=?');$c->execute([$cat,$tenantId]);if(!$c->fetchColumn())throw new RuntimeException('Categoria inválida.');}
        $args=[$u?:null,$cat?:null,$name,trim((string)($_POST['description']??'')),$sku?:null,$price,$promo,$stock,$minStock,$track,max(0,(int)($_POST['preparation_minutes']??0))?:null,trim((string)($_POST['badge']??''))?:null,isset($_POST['featured'])?1:0,trim((string)($_POST['image_url']??''))?:null,isset($_POST['active'])?1:0];
        if($id){$pdo->prepare('UPDATE products SET unit_id=?,category_id=?,name=?,description=?,sku=?,price_cents=?,promo_price_cents=?,stock_qty=?,min_stock_qty=?,track_stock=?,preparation_minutes=?,badge=?,featured=?,image_url=?,active=? WHERE id=? AND tenant_id=?')->execute([...$args,$id,$tenantId]);}else{$pdo->prepare('INSERT INTO products (tenant_id,unit_id,category_id,name,description,sku,price_cents,promo_price_cents,stock_qty,min_stock_qty,track_stock,preparation_minutes,badge,featured,image_url,active) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)')->execute([$tenantId,...$args]);$id=(int)$pdo->lastInsertId();}Auth::audit('product.saved','product',(string)$id);em_flash('ok','Produto salvo com sucesso.');
    }
    elseif($action==='product-toggle'){$pdo->prepare('UPDATE products SET active=1-active WHERE id=? AND tenant_id=?')->execute([(int)$_POST['id'],$tenantId]);em_flash('ok','Status do produto alterado.');}
    elseif($action==='product-delete'){$id=(int)$_POST['id'];$used=$pdo->prepare('SELECT COUNT(*) FROM order_items WHERE product_id=?');$used->execute([$id]);if((int)$used->fetchColumn()>0){$pdo->prepare('UPDATE products SET active=0 WHERE id=? AND tenant_id=?')->execute([$id,$tenantId]);em_flash('ok','Produto já possui histórico e foi arquivado.');}else{$pdo->prepare('DELETE FROM products WHERE id=? AND tenant_id=?')->execute([$id,$tenantId]);em_flash('ok','Produto excluído.');}}
    elseif($action==='product-duplicate'){$source=(int)$_POST['id'];Database::transaction(function(PDO$db)use($tenantId,$source){$s=$db->prepare('SELECT * FROM products WHERE id=? AND tenant_id=? FOR UPDATE');$s->execute([$source,$tenantId]);$p=$s->fetch();if(!$p)throw new RuntimeException('Produto não encontrado.');$db->prepare('INSERT INTO products (tenant_id,unit_id,category_id,product_type,name,description,sku,price_cents,promo_price_cents,stock_qty,min_stock_qty,track_stock,preparation_minutes,badge,featured,image_url,active) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,0)')->execute([$tenantId,$p['unit_id'],$p['category_id'],$p['product_type'],$p['name'].' (cópia)',$p['description'],null,$p['price_cents'],$p['promo_price_cents'],$p['stock_qty'],$p['min_stock_qty'],$p['track_stock'],$p['preparation_minutes'],$p['badge'],$p['featured'],$p['image_url']]);$new=(int)$db->lastInsertId();$groups=$db->prepare('SELECT * FROM product_option_groups WHERE tenant_id=? AND product_id=? ORDER BY id');$groups->execute([$tenantId,$source]);foreach($groups->fetchAll()as$g){$db->prepare('INSERT INTO product_option_groups (tenant_id,product_id,name,min_select,max_select,sort_order,active) VALUES (?,?,?,?,?,?,?)')->execute([$tenantId,$new,$g['name'],$g['min_select'],$g['max_select'],$g['sort_order'],$g['active']]);$ng=(int)$db->lastInsertId();$opts=$db->prepare('SELECT * FROM product_options WHERE group_id=?');$opts->execute([$g['id']]);foreach($opts->fetchAll()as$o)$db->prepare('INSERT INTO product_options (tenant_id,group_id,name,price_delta_cents,sort_order,active) VALUES (?,?,?,?,?,?)')->execute([$tenantId,$ng,$o['name'],$o['price_delta_cents'],$o['sort_order'],$o['active']]);}$combo=$db->prepare('SELECT component_product_id,quantity FROM product_combo_items WHERE tenant_id=? AND combo_product_id=?');$combo->execute([$tenantId,$source]);foreach($combo->fetchAll()as$c)$db->prepare('INSERT INTO product_combo_items (tenant_id,combo_product_id,component_product_id,quantity) VALUES (?,?,?,?)')->execute([$tenantId,$new,$c['component_product_id'],$c['quantity']]);Auth::audit('product.duplicated','product',(string)$new,['source'=>$source]);});em_flash('ok','Produto duplicado como inativo para revisão.');}
}catch(Throwable$e){em_flash('error',$e->getMessage());}em_go('products',isset($id)&&$id?['edit'=>$id]:[]);}
$editId=(int)($_GET['edit']??0);$edit=null;if($editId){$s=$pdo->prepare('SELECT * FROM products WHERE id=? AND tenant_id=?');$s->execute([$editId,$tenantId]);$edit=$s->fetch()?:null;}$units=$pdo->prepare('SELECT id,name FROM business_units WHERE tenant_id=? AND status="active" ORDER BY name');$units->execute([$tenantId]);$units=$units->fetchAll();$cats=$pdo->prepare('SELECT * FROM categories WHERE tenant_id=? ORDER BY sort_order,name');$cats->execute([$tenantId]);$categories=$cats->fetchAll();$sql='SELECT p.*,c.name category_name,bu.name unit_name FROM products p LEFT JOIN categories c ON c.id=p.category_id LEFT JOIN business_units bu ON bu.id=p.unit_id WHERE p.tenant_id=?';$args=[$tenantId];if($unitId){$sql.=' AND (p.unit_id IS NULL OR p.unit_id=?)';$args[]=$unitId;}$sql.=' ORDER BY p.active DESC,p.featured DESC,p.id DESC';$s=$pdo->prepare($sql);$s->execute($args);$products=$s->fetchAll();em_header('Cardápio e produtos','products');?>
<div class="grid" style="grid-template-columns:minmax(300px,1fr) minmax(0,2fr)"><section class="card"><h2><?= $edit?'Editar produto':'Novo produto' ?></h2><form method="post" class="form-grid"><input type="hidden" name="_csrf" value="<?= em_csrf() ?>"><input type="hidden" name="action" value="product-save"><input type="hidden" name="id" value="<?= (int)($edit['id']??0) ?>"><label class="span-2">Nome<input name="name" required value="<?= Security::e($edit['name']??'') ?>"></label><label>Preço normal<input name="price" required inputmode="decimal" value="<?= $edit?Security::e(number_format(((int)$edit['price_cents'])/100,2,',','')):'' ?>"></label><label>Preço promocional<input name="promo_price" inputmode="decimal" value="<?= !empty($edit['promo_price_cents'])?Security::e(number_format(((int)$edit['promo_price_cents'])/100,2,',','')):'' ?>"></label><label>SKU<input name="sku" value="<?= Security::e($edit['sku']??'') ?>"></label><label>Unidade<select name="unit_id"><option value="0">Compartilhado / todas</option><?php foreach($units as$u):?><option value="<?= (int)$u['id'] ?>"<?= em_selected($edit['unit_id']??$unitId,$u['id']) ?>><?= Security::e($u['name']) ?></option><?php endforeach;?></select></label><label class="span-2">Categoria<select name="category_id"><option value="0">Sem categoria</option><?php foreach($categories as$c):?><option value="<?= (int)$c['id'] ?>"<?= em_selected($edit['category_id']??0,$c['id']) ?>><?= Security::e($c['name']) ?></option><?php endforeach;?></select></label><label>Estoque<input name="stock_qty" inputmode="decimal" value="<?= Security::e((string)($edit['stock_qty']??'0')) ?>"></label><label>Estoque mínimo<input name="min_stock_qty" inputmode="decimal" value="<?= Security::e((string)($edit['min_stock_qty']??'0')) ?>"></label><label>Preparo (min)<input type="number" min="0" name="preparation_minutes" value="<?= Security::e((string)($edit['preparation_minutes']??'')) ?>"></label><label>Selo<input name="badge" value="<?= Security::e($edit['badge']??'') ?>" placeholder="Mais vendido"></label><label class="span-2">Imagem (URL)<input type="url" name="image_url" value="<?= Security::e($edit['image_url']??'') ?>"></label><label class="span-2">Descrição<textarea name="description"><?= Security::e($edit['description']??'') ?></textarea></label><label class="checkbox"><input type="checkbox" name="track_stock"<?= em_checked($edit['track_stock']??0) ?>> Controlar estoque</label><label class="checkbox"><input type="checkbox" name="featured"<?= em_checked($edit['featured']??0) ?>> Destaque</label><label class="checkbox span-2"><input type="checkbox" name="active"<?= em_checked($edit?($edit['active']??0):1) ?>> Produto ativo</label><button class="primary span-2">Salvar produto</button><?php if($edit):?><a class="button secondary" href="<?= Security::e(em_url('/?route=product-options&id='.(int)$edit['id'])) ?>">Opções / adicionais / combo</a><a class="button secondary" href="<?= Security::e(em_url('/?route=products')) ?>">Cancelar edição</a><?php endif;?></form><hr style="border-color:var(--line);margin:24px 0"><h3>Categoria</h3><form method="post" class="form-grid"><input type="hidden" name="_csrf" value="<?= em_csrf() ?>"><input type="hidden" name="action" value="category-save"><label class="span-2">Nome<input name="name" required></label><label>Unidade<select name="unit_id"><option value="0">Todas</option><?php foreach($units as$u):?><option value="<?= (int)$u['id'] ?>"<?= em_selected($unitId,$u['id']) ?>><?= Security::e($u['name']) ?></option><?php endforeach;?></select></label><label>Ordem<input type="number" name="sort_order" value="0"></label><input type="hidden" name="active" value="1"><button class="secondary span-2">Criar categoria</button></form></section><section class="card"><div class="section-head"><h2>Produtos</h2><span class="muted"><?= count($products) ?> cadastrados</span></div><div class="table-wrap"><table class="table"><thead><tr><th>Produto</th><th>Unidade</th><th>Preço</th><th>Estoque</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($products as$p):?><tr><td><strong><?= Security::e($p['name']) ?></strong><?php if($p['featured']):?> <span class="badge">Destaque</span><?php endif;?><?php if($p['badge']):?> <span class="badge"><?= Security::e($p['badge']) ?></span><?php endif;?><br><span class="muted"><?= Security::e(($p['category_name']??'Sem categoria').' · '.($p['sku']??'')) ?></span></td><td><?= Security::e($p['unit_name']??'Todas') ?></td><td><?php if($p['promo_price_cents']!==null):?><s class="muted"><?= em_money($p['price_cents']) ?></s><br><strong><?= em_money($p['promo_price_cents']) ?></strong><?php else:?><?= em_money($p['price_cents']) ?><?php endif;?></td><td><?= $p['track_stock']?Security::e((string)$p['stock_qty']).(!empty($p['min_stock_qty'])?' / mín. '.Security::e((string)$p['min_stock_qty']):''):'Livre' ?></td><td><span class="badge"><?= $p['active']?'Ativo':'Pausado' ?></span></td><td><div class="actions"><a class="button secondary" href="<?= Security::e(em_url('/?route=products&edit='.(int)$p['id'])) ?>">Editar</a><a class="button secondary" href="<?= Security::e(em_url('/?route=product-options&id='.(int)$p['id'])) ?>">Opções</a><form method="post"><input type="hidden" name="_csrf" value="<?= em_csrf() ?>"><input type="hidden" name="action" value="product-toggle"><input type="hidden" name="id" value="<?= (int)$p['id'] ?>"><button class="secondary"><?= $p['active']?'Pausar':'Ativar' ?></button></form><form method="post"><input type="hidden" name="_csrf" value="<?= em_csrf() ?>"><input type="hidden" name="action" value="product-duplicate"><input type="hidden" name="id" value="<?= (int)$p['id'] ?>"><button class="secondary">Duplicar</button></form></div></td></tr><?php endforeach;?></tbody></table></div><h3 style="margin-top:24px">Categorias</h3><div class="table-wrap"><table class="table"><tbody><?php foreach($categories as$c):?><tr><td><?= Security::e($c['name']) ?></td><td><?= $c['active']?'Ativa':'Inativa' ?></td><td><div class="actions"><form method="post"><input type="hidden" name="_csrf" value="<?= em_csrf() ?>"><input type="hidden" name="action" value="category-toggle"><input type="hidden" name="id" value="<?= (int)$c['id'] ?>"><button class="secondary">Alternar</button></form><form method="post" onsubmit="return confirm('Excluir categoria?')"><input type="hidden" name="_csrf" value="<?= em_csrf() ?>"><input type="hidden" name="action" value="category-delete"><input type="hidden" name="id" value="<?= (int)$c['id'] ?>"><button class="secondary">Excluir</button></form></div></td></tr><?php endforeach;?></tbody></table></div></section></div><?php em_footer();
